// tools/embed-select.mjsによる生成物。承認済みse-select.wavの16bit PCMを保持。
const pcm = '';

export function createSelectBuffer(context) {
  const bytes = atob(pcm);
  const buffer = context.createBuffer(2, 15435, 44100);
  for (let channel = 0; channel < 2; channel++) {
    const data = buffer.getChannelData(channel);
    for (let frame = 0; frame < 15435; frame++) {
      const i = (frame * 2 + channel) * 2;
      const sample = bytes.charCodeAt(i) | (bytes.charCodeAt(i + 1) << 8);
      data[frame] = (sample >= 32768 ? sample - 65536 : sample) / 32768;
    }
  }
  return buffer;
}
